function uuidv4() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; const v = c === 'x' ? r : (r & 0x3 | 0x8); return v.toString(16); }); }
const raw = $input.first().json;
const f = raw.body ?? raw;
const jobId = f.jobId || uuidv4();
const niche = (f.niche || 'news-europe').trim();
const sourceUrls = String(f.sourceUrls || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const sourceSummaries = String(f.sourceSummaries || '').split(/\r?\n/).map(s => s.trim()).filter(Boolean);
const trend = { jobId, topic: f.topic, angle: f.angle || f.topic, sourceUrls, sourceSummaries };
const RESOLUTION_PRESETS = {'480p':{width:854,height:480},'720p':{width:1280,height:720},'1080p':{width:1920,height:1080},'2k':{width:2560,height:1440},'4k':{width:3840,height:2160}};
const resolution = RESOLUTION_PRESETS[String(f.resolution || '1080p').trim().toLowerCase()] || RESOLUTION_PRESETS['1080p'];
function b64(obj) { return Buffer.from(JSON.stringify(obj)).toString('base64'); }
return [{ json: { jobId, niche, topic: f.topic, angle: f.angle || f.topic, trendB64: b64(trend), reviewStateB64: b64({ jobId, resolution }) } }];

const ctx = $('Job Context').first().json;
const payload = { jobId: ctx.jobId, mode: 'manual', status: 'running', currentStep: 'script-generator', niche: ctx.niche };
return [{ json: { ...ctx, updateJobB64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];

const GH_API = 'https://api.github.com/repos/' + $env.GITHUB_REPO;
const HEADERS = { Authorization: 'Bearer ' + $env.GITHUB_TOKEN, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' };
const jobId = $('Job Context').first().json.jobId;
const dispatchedAt = Date.now();

await this.helpers.httpRequest({
  method: 'POST',
  url: GH_API + '/actions/workflows/02-generate-script.yml/dispatches',
  headers: HEADERS,
  body: { ref: 'master', inputs: { jobId } },
  json: true,
});

const maxWaitMs = 20 * 60 * 1000;
const pollIntervalMs = 15000;
let run = null;
while (Date.now() - dispatchedAt < maxWaitMs) {
  await new Promise((resolve) => setTimeout(resolve, pollIntervalMs));
  let body;
  try {
    body = await this.helpers.httpRequest({
      method: 'GET',
      url: GH_API + '/actions/workflows/02-generate-script.yml/runs?event=workflow_dispatch&per_page=5',
      headers: HEADERS,
      json: true,
    });
  } catch (e) { continue; }
  const candidates = (body.workflow_runs || [])
    .filter((r) => new Date(r.created_at).getTime() >= dispatchedAt - 5000)
    .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  if (candidates.length > 0) {
    run = candidates[0];
    if (run.status === 'completed') break;
  }
}

const succeeded = !!run && run.status === 'completed' && run.conclusion === 'success';
return [{ json: { succeeded, runId: run ? run.id : null, htmlUrl: run ? run.html_url : null, status: run ? run.status : null, conclusion: run ? run.conclusion : null } }];

